`resolveBindings(modules, requests)` resolves named values from module-like namespace objects without executing code.

`modules` must be a non-array object whose own properties are module IDs. `requests` must be an array. Each request must be a non-array object with non-empty string properties `from`, `imported`, and `local`. `local` must match `/^[A-Za-z_$][A-Za-z0-9_$]*$/`, and local names must be distinct. A requested module must be an own property of `modules` and its namespace must be a non-null object or function. The imported name must be an own property of that namespace. Imported values may validly be `undefined`, `null`, `false`, `0`, or an empty string.

Throw `TypeError` for malformed containers or request fields, `RangeError` for duplicate local names, and `ReferenceError` for a missing module or binding. Validate requests in array order and stop at the first error.

Return a new ordinary object with bindings defined in request order. Never mutate inputs. Preserve imported values by identity; only the returned container is detached.

Known-bad source:

'use strict';

function isObjectLike(value) {
  return value !== null && (typeof value === 'object' || typeof value === 'function');
}

function resolveBindings(modules, requests) {
  if (!isObjectLike(modules) || Array.isArray(modules)) {
    throw new TypeError('modules must be an object');
  }
  if (!Array.isArray(requests)) throw new TypeError('requests must be an array');

  const result = {};
  const locals = new Set();
  for (const request of requests) {
    if (!isObjectLike(request) || Array.isArray(request)) {
      throw new TypeError('request must be an object');
    }
    for (const field of ['from', 'imported', 'local']) {
      if (typeof request[field] !== 'string' || request[field] === '') {
        throw new TypeError(field + ' must be a non-empty string');
      }
    }
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(request.local)) {
      throw new TypeError('invalid local name');
    }
    if (locals.has(request.local)) throw new RangeError('duplicate local name');
    locals.add(request.local);

    if (!Object.prototype.hasOwnProperty.call(modules, request.from)) {
      throw new ReferenceError('missing module');
    }
    const namespace = modules[request.from];
    if (!isObjectLike(namespace)) throw new TypeError('namespace must be object-like');
    if (!namespace[request.imported]) throw new ReferenceError('missing binding');

    Object.defineProperty(result, request.local, {
      value: namespace[request.imported],
      enumerable: true,
      writable: true,
      configurable: true
    });
  }
  return result;
}

module.exports = { resolveBindings };

