'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['resolveBindings']);
const { resolveBindings } = api;

assert.throws(() => resolveBindings(null, []), TypeError);
assert.throws(() => resolveBindings([], []), TypeError);
assert.throws(() => resolveBindings({}, null), TypeError);
assert.throws(() => resolveBindings({}, [null]), TypeError);
assert.throws(() => resolveBindings({}, [{ from: '', imported: 'x', local: 'x' }]), TypeError);
assert.throws(() => resolveBindings({}, [{ from: 'm', imported: 1, local: 'x' }]), TypeError);
assert.throws(() => resolveBindings({}, [{ from: 'm', imported: 'x', local: 'bad-name' }]), TypeError);
assert.throws(() => resolveBindings({ m: {} }, [
  { from: 'm', imported: 'a', local: 'x' },
  { from: 'm', imported: 'b', local: 'x' }
]), RangeError);
assert.throws(() => resolveBindings({}, [{ from: 'missing', imported: 'x', local: 'x' }]), ReferenceError);
assert.throws(() => resolveBindings({ m: null }, [{ from: 'm', imported: 'x', local: 'x' }]), TypeError);
assert.throws(() => resolveBindings({ m: {} }, [{ from: 'm', imported: 'toString', local: 'x' }]), ReferenceError);

const identity = {};
const namespace = Object.create({ inherited: 1 });
Object.assign(namespace, { undef: undefined, nil: null, nope: false, zero: 0, empty: '', object: identity });
const modules = { m: namespace };
const requests = [
  { from: 'm', imported: 'undef', local: 'u' },
  { from: 'm', imported: 'nil', local: 'n' },
  { from: 'm', imported: 'nope', local: 'f' },
  { from: 'm', imported: 'zero', local: '$zero' },
  { from: 'm', imported: 'empty', local: '_empty' },
  { from: 'm', imported: 'object', local: 'obj' }
];
const result = resolveBindings(modules, requests);
assert.strictEqual(Object.getPrototypeOf(result), Object.prototype);
assert.deepStrictEqual(Object.keys(result), ['u', 'n', 'f', '$zero', '_empty', 'obj']);
assert.strictEqual(result.u, undefined);
assert.strictEqual(result.n, null);
assert.strictEqual(result.f, false);
assert.strictEqual(result.$zero, 0);
assert.strictEqual(result._empty, '');
assert.strictEqual(result.obj, identity);
assert.notStrictEqual(result, modules);
requests.reverse();
modules.m = {};
assert.strictEqual(result.obj, identity);

const second = resolveBindings({ m: namespace }, [{ from: 'm', imported: 'zero', local: '__proto__' }]);
assert.deepStrictEqual(Object.keys(second), ['__proto__']);
assert.strictEqual(second.__proto__, 0);
assert.strictEqual(Object.getPrototypeOf(second), Object.prototype);
assert.throws(() => resolveBindings({ m: namespace }, [{ from: 'm', imported: 'inherited', local: 'x' }]), ReferenceError);

